toolScript:
let isRunning = false;
        let count = 0;
        let audioCtx = null;
        let nextBeatTime = 0;
        const bpm = 110;
        const secondsPerBeat = 60 / bpm;
        let timer = null;
        // Gamification Variables
        let isPracticeMode = false;
        let lastBeatTimestamp = 0; // The actual time the last beat happened
        let streak = 0;
        const heartUI = document.getElementById('heart-ui');
        const countDisplay = document.getElementById('comp-count');
        const actionText = document.getElementById('action-text');
        const practiceToggle = document.getElementById('practice-toggle');
        const streakContainer = document.getElementById('streak-container');
        const streakCountSpan = document.getElementById('streak-count');
        const feedbackArea = document.getElementById('feedback-area');
        // Toggle Practice Mode
        practiceToggle.addEventListener('change', (e) => {
            isPracticeMode = e.target.checked;
            resetCounter();
            streak = 0;
            updateStreakUI();
            const badge = document.getElementById('mode-badge');
            if (isPracticeMode) {
                badge.innerText = "TRAINING MODE";
                badge.classList.remove('bg-red-600');
                badge.classList.add('bg-emerald-600');
                streakContainer.classList.remove('hidden', 'opacity-0');
                streakContainer.classList.add('opacity-100', 'translate-y-0');
                document.getElementById('keyboard-hint').classList.remove('hidden');
                // Show hint immediately
                showFeedback("TAP TO BEAT", "text-slate-400");
            } else {
                badge.innerText = "EMERGENCY PROTOCOL";
                badge.classList.remove('bg-emerald-600');
                badge.classList.add('bg-red-600');
                streakContainer.classList.add('hidden', 'opacity-0');
                document.getElementById('keyboard-hint').classList.add('hidden');
            }
        });
        function toggleMetronome() {
            if (isRunning) {
                stop();
            } else {
                start();
            }
        }
        function start() {
            if (!audioCtx) {
                const AudioContext = window.AudioContext || window.webkitAudioContext;
                audioCtx = new AudioContext();
            }
            if (audioCtx.state === 'suspended') {
                audioCtx.resume();
            }
            isRunning = true;
            count = 0;
            countDisplay.innerText = "0";
            document.getElementById('btn-text').innerText = "STOP PACE";
            document.getElementById('btn-icon').innerText = "Stop";
            document.getElementById('connection-status').innerText = "Audio: ACTIVE";
            document.getElementById('main-btn').classList.replace('bg-red-600', 'bg-slate-800');
            nextBeatTime = audioCtx.currentTime;
            scheduler();
        }
        function stop() {
            isRunning = false;
            clearTimeout(timer);
            document.getElementById('btn-text').innerText = "START BEAT";
            document.getElementById('btn-icon').innerText = "Play";
            document.getElementById('connection-status').innerText = "Audio: Standby";
            document.getElementById('main-btn').classList.replace('bg-slate-800', 'bg-red-600');
            heartUI.classList.remove('beat', 'perfect-hit');
            actionText.innerText = "READY";
            // Reset streak on stop
            streak = 0;
            updateStreakUI();
        }
        function scheduler() {
            while (nextBeatTime < audioCtx.currentTime + 0.1) {
                scheduleBeat(nextBeatTime);
                nextBeatTime += secondsPerBeat;
            }
            timer = setTimeout(scheduler, 25);
        }
        function scheduleBeat(time) {
            const osc = audioCtx.createOscillator();
            const envelope = audioCtx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(1000, time);
            envelope.gain.setValueAtTime(1, time);
            envelope.gain.exponentialRampToValueAtTime(0.001, time + 0.08);
            osc.connect(envelope);
            envelope.connect(audioCtx.destination);
            osc.start(time);
            osc.stop(time + 0.08);
            const delay = (time - audioCtx.currentTime) * 1000;
            // Sync Visuals
            setTimeout(() => {
                if (!isRunning) return;
                // Track last beat time for practice mode
                lastBeatTimestamp = Date.now();
                heartUI.classList.add('beat');
                count++;
                countDisplay.innerText = count;
                countDisplay.style.color = '#ffffff';
                actionText.innerText = "PUSH";
                actionText.style.color = '#fecaca';
                setTimeout(() => {
                    heartUI.classList.remove('beat');
                    countDisplay.style.color = '#0f172a';
                    actionText.innerText = "RECOIL";
                    actionText.style.color = '#94a3b8';
                }, 120);
            }, delay);
        }
        function resetCounter() {
            count = 0;
            streak = 0;
            updateStreakUI();
            countDisplay.innerText = "0";
        }
        // --- INTERACTIVE PRACTICE MODE LOGIC ---
        function handleInteraction() {
            if (!isRunning || !isPracticeMode) {
                // If not running and in practice mode, start it
                if (isPracticeMode && !isRunning) toggleMetronome();
                return;
            }
            const now = Date.now();
            const timeDiff = Math.abs(now - lastBeatTimestamp);
            // 110 BPM = 545ms interval. 
            // Window: <100ms = Perfect, <200ms = Good, >200ms = Miss
            if (timeDiff < 120) {
                // Perfect Hit
                streak++;
                showFeedback("PERFECT!", "text-emerald-500");
                heartUI.classList.add('perfect-hit');
                setTimeout(() => heartUI.classList.remove('perfect-hit'), 150);
                triggerDopamineSound('perfect');
            } else if (timeDiff < 250) {
                // Good Hit
                streak++; // Keep streak but maybe visually distinct?
                showFeedback("GOOD", "text-blue-500");
            } else {
                // Miss
                streak = 0;
                showFeedback("MISS", "text-red-500");
            }
            updateStreakUI();
        }
        // Listen for Spacebar
        document.addEventListener('keydown', (e) => {
            if (e.code === 'Space' && isPracticeMode) {
                e.preventDefault(); // Prevent scrolling
                handleInteraction();
                // Visual feedback on the heart to show key press registered
                heartUI.style.transform = "scale(0.95)";
                setTimeout(() => heartUI.style.transform = "", 50);
            }
        });
        function showFeedback(text, colorClass) {
            const el = document.createElement('div');
            el.innerText = text;
            el.className = `feedback-text text-2xl ${colorClass}`;
            // Randomize position slightly
            const randomX = (Math.random() - 0.5) * 40;
            el.style.transform = `translateX(${randomX}px)`;
            feedbackArea.appendChild(el);
            // Cleanup
            setTimeout(() => {
                el.remove();
            }, 800);
        }
        function updateStreakUI() {
            streakCountSpan.innerText = streak;
            if (streak > 0 && streak % 10 === 0) {
                // Milestone visual
                streakCountSpan.classList.add('text-orange-500', 'scale-150');
                setTimeout(() => streakCountSpan.classList.remove('text-orange-500', 'scale-150'), 200);
            }
        }
        // Simple synth for feedback sounds (Dopamine hits)
        function triggerDopamineSound(type) {
            if (!audioCtx) return;
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            osc.connect(gain);
            gain.connect(audioCtx.destination);
            if (type === 'perfect') {
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(880, audioCtx.currentTime); // High A
                osc.frequency.exponentialRampToValueAtTime(1760, audioCtx.currentTime + 0.1);
                gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
                gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.1);
                osc.start();
                osc.stop(audioCtx.currentTime + 0.1);
            }
        }
        // --- TUTORIAL LOGIC ---
        const tutorialSteps = [
            {
                elementId: 'main-btn',
                title: "Start the Pacer",
                desc: "Click here to start the 110 BPM audio and visual rhythm engine. This is your primary control."
            },
            {
                elementId: 'heart-wrapper',
                title: "Visual & Interactive Heart",
                desc: "This ring flashes with the beat. In 'Practice Mode', click this or press Spacebar to test your rhythm accuracy!"
            },
            {
                elementId: 'practice-toggle-container',
                title: "Toggle Training Mode",
                desc: "Switch this on to gamify your learning. Get feedback on your timing and build muscle memory."
            },
            {
                elementId: 'comp-count',
                title: "Compression Counter",
                desc: "Keeps track of your cycle. Remember: 30 compressions, then 2 breaths (if trained)."
            }
        ];
        let currentStep = 0;
        function startTutorial() {
            currentStep = 0;
            document.getElementById('tutorial-overlay').classList.remove('hidden');
            // Small delay to allow display block to render before opacity transition
            setTimeout(() => {
                document.getElementById('tutorial-overlay').classList.add('tutorial-active');
                showTutorialStep();
            }, 10);
        }
        function showTutorialStep() {
            if (currentStep >= tutorialSteps.length) {
                closeTutorial();
                return;
            }
            const step = tutorialSteps[currentStep];
            const targetEl = document.getElementById(step.elementId);
            const spotlight = document.getElementById('tutorial-spotlight');
            const card = document.getElementById('tutorial-card');
            const rect = targetEl.getBoundingClientRect();
            // Move Spotlight
            spotlight.style.width = `${rect.width + 20}px`;
            spotlight.style.height = `${rect.height + 20}px`;
            spotlight.style.top = `${rect.top - 10}px`;
            spotlight.style.left = `${rect.left - 10}px`;
            // Move Card (Smart positioning)
            const cardX = window.innerWidth < 768 ? (window.innerWidth / 2 - 140) : (rect.right + 20);
            const cardY = rect.top;
            // Check if card goes off screen right
            if (cardX + 280 > window.innerWidth) {
                card.style.left = `${rect.left - 300}px`; // Move to left
            } else {
                card.style.left = `${cardX}px`;
            }
            // Mobile check
            if (window.innerWidth < 768) {
                card.style.left = `50%`;
                card.style.transform = `translateX(-50%)`;
                card.style.top = `${rect.bottom + 20}px`;
            } else {
                card.style.top = `${cardY}px`;
                card.style.transform = `none`;
            }
            // Content
            document.getElementById('tut-title').innerText = step.title;
            document.getElementById('tut-desc').innerText = step.desc;
            document.getElementById('tut-step').innerText = `${currentStep + 1}/${tutorialSteps.length}`;
        }
        function nextTutorialStep() {
            currentStep++;
            showTutorialStep();
        }
        function closeTutorial() {
            document.getElementById('tutorial-overlay').classList.remove('tutorial-active');
            setTimeout(() => {
                document.getElementById('tutorial-overlay').classList.add('hidden');
            }, 300);
            localStorage.setItem('cpr_tutorial_seen', 'true');
        }
        // Auto-start tutorial on first visit
        window.addEventListener('load', () => {
            if (!localStorage.getItem('cpr_tutorial_seen')) {
                setTimeout(startTutorial, 1000);
            }
        });
        // --- GLOBAL SCROLL LOGIC ---
